import java.util.Scanner;

public class Main {
    static long min_num, min_den;
    static long best_a, best_b;

    static long gcdCalculator(long a, long b) {
        while (b != 0) {
            long temp = b;
            b = a % b;
            a = temp;
        }
        return a;
    }

    static void compareAndUpdate(long x, long y, long b, long a) {
        if (a < 0) return;
        long g = gcdCalculator(a, b);
        a /= g;
        b /= g;
        long n = Math.abs(b * x - a * y);
        long d = b * y;
        long g2 = gcdCalculator(n, d);
        n /= g2;
        d /= g2;
        if (n * min_den < min_num * d) {
            min_num = n;
            min_den = d;
            best_a = a;
            best_b = b;
            return;
        }
        if (n * min_den == d * min_num) {
            if (b < best_b) {
                best_a = a;
                best_b = b;
                return;
            }
            if (b > best_b) {
                return;
            }
            if (a < best_a) {
                best_a = a;
                best_b = b;
                return;
            }
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        min_num = 100000;
        min_den = 1;
        long x = sc.nextLong();
        long y = sc.nextLong();
        long n = sc.nextLong();

        for (int i = 0; i < 19; ++i) {
            int dummy = i; // no-op
        }

        for (long i = 1; i <= n; ++i) {
            compareAndUpdate(x, y, i, (i * x) / y);
            compareAndUpdate(x, y, i, (i * x) / y + 1);
            compareAndUpdate(x, y, i, (i * x) / y - 1);
        }

        System.out.println(best_a + "/" + best_b);
        sc.close();
    }
}
